-- Add the workspace selection page to platform management without granting new permissions.
INSERT INTO sys_menu (id, parent_id, menu_code, menu_name, menu_type, route_path, icon, sort_order, status, created_at, updated_at)
SELECT 'ws-selection-menu', p.id, 'workspaces', '工作空间', 'menu', '/index.html#/w/zhice/workspaces', 'grid', 37, 'enabled', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM sys_menu p WHERE p.menu_code = 'platform' AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE menu_code = 'workspaces');

INSERT INTO sys_menu_permission (id, menu_id, permission_id, created_at, updated_at)
SELECT 'ws-selection-access', m.id, p.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM sys_menu m JOIN sys_permission p ON p.permission_code = 'workspace:zhice:access'
WHERE m.menu_code = 'workspaces' AND NOT EXISTS (SELECT 1 FROM sys_menu_permission WHERE menu_id = m.id)
AND NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-management:v1');

-- Apply the requested platform default once; later administrator choices remain authoritative.
UPDATE workspace_registry SET default_workspace = CASE WHEN id = 'zhice' THEN TRUE ELSE FALSE END,
version = version + 1, updated_at = CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-management:v1');
INSERT INTO sys_permission (id, permission_code, permission_name, permission_type, status, sort_order, created_at, updated_at)
SELECT 'ws-management-marker', 'system:workspace-management:v1', 'Workspace management migration V1', 'internal', 'enabled', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-management:v1');

